'use strict';
const Core=globalThis.BMHCore;
const oldValidate=validateProject;
validateProject=function(s){const d=oldValidate(s),extra=Core.validateUpgrade(Object.fromEntries(Object.keys(Core.defaultUpgrade()).filter(k=>s[k]!==undefined).map(k=>[k,s[k]])));const out={...d,...extra};Core.buildSnapshot(out);return out;};
let recoveryWarning='';try{state=validateProject(state);}catch(e){state={...structuredClone(defaults),...Core.defaultUpgrade()};recoveryWarning='Dữ liệu lưu không hợp lệ: '+e.message+'. Bản lưu cũ chưa bị ghi đè; hãy tải bản JSON cũ nếu cần phục hồi.';}
let cachedKey='',cachedSnapshot=null,aiResult=null,aiBusy=false;
function snapshot(){const input={...state,snapshots:[],step:0,floor:0,selected:''};const key=JSON.stringify(input)+new Date().toISOString().slice(0,10);if(key!==cachedKey){cachedSnapshot=Core.buildSnapshot(state);cachedKey=key;}return cachedSnapshot;}
schedule=function(){return snapshot().loans.map(r=>({month:r.month,principal:r.principalPaid,interest:r.interest,fee:r.fee,total:r.payment,balance:r.closingBalance,draw:r.loanDraw}));};
calc=function(){const s=snapshot(),q=s.quote,by=id=>q.items.find(i=>i.id===id)?.total??0;return{snapshot:s,area:s.geometry.floorArea,shell:by('structure'),finish:q.baseTotal-by('structure')-by('preparation'),transport:0,prep:by('preparation'),contingency:q.constructionContingency,total:q.total,budget:s.budget,first:s.loans[0]?.payment??0,post:s.loans[Math.min(state.promo,s.loans.length-1)]?.payment??0,remainder:s.monthlyRemainder,loans:schedule(),dt:s.netDebtRatio===null?null:100*s.netDebtRatio};};
rows=function(c){return [...c.snapshot.quote.items.map(i=>[i.description,i.total]),['Dự phòng công trình',c.contingency]];};
function statusNote(s){return `<div class="notice ${s.geometry.valid?'':'danger'}"><b>${esc(s.id)}</b> · ${s.status==='invalid_geometry'?'BẢN NHÁP — cần sửa hình học':s.status==='incomplete'?'CHƯA ĐỦ GIÁ — tổng chỉ gồm phần có giá':'Dự toán ý tưởng'}<br>${s.priceFlags.length?'Có giá minh họa/nguồn cần kiểm tra.':'Giá do người dùng nhập; chưa xác minh nhà cung cấp.'} ${s.missing.length?'Thiếu: '+s.missing.map(esc).join(', '):''}</div>`;}
table=function(c){const s=c.snapshot;return statusNote(s)+`<div class="tablewrap"><table><thead><tr><th>Hạng mục / nguồn giá</th><th>Khối lượng</th><th>Đơn giá</th><th class="num">Thành tiền</th></tr></thead><tbody>${s.quote.items.map(i=>`<tr><td>${esc(i.description)}<small class="source">${esc(i.priceSource)} · ${esc(i.priceDate)} · ${esc(i.region)}${i.sourceUrl?' · <a href="'+esc(i.sourceUrl)+'" target="_blank" rel="noopener noreferrer">Nguồn</a>':''}</small></td><td>${num(i.quantityWithWaste)} ${esc(i.unit)}</td><td>${money(i.unitPrice)}<small class="source">Thuế ${num(i.taxRate*100)}%</small></td><td class="num">${money(i.total)}</td></tr>`).join('')}<tr><td colspan="3">Dự phòng ${num(state.contingencyRate*100)}%</td><td class="num">${money(s.quote.constructionContingency)}</td></tr><tr class="total"><td colspan="3">Tổng phần đã tính</td><td class="num">${money(s.quote.total)}</td></tr></tbody></table></div>`;};
const originalEditor=editor;
editor=function(c){const g=c.snapshot.geometry;return originalEditor(c)+`<section class="card upgrade"><h2>Tường, cửa & khối lượng chung</h2><p class="hint">Phòng theo tim tường. Đoạn tường chung chỉ tính một lần. Khối lượng sơ bộ chưa trừ các nút giao tường; không dùng như bóc thép/móng.</p><div class="fields">${field('Chiều cao tầng · m','wallHeight',{min:2,max:6,step:.1})}${field('Dày tường · m','wallThickness',{min:.05,max:.6,step:.01})}</div><div class="metrics4"><div class="metric"><small>Diện tích hợp</small><strong>${num(g.floorArea)} m²</strong></div><div class="metric"><small>Tường duy nhất</small><strong>${num(g.wallLength)} m</strong></div><div class="metric"><small>Tường trừ cửa</small><strong>${num(g.wallArea)} m²</strong></div><div class="metric"><small>Thể tích tường sơ bộ</small><strong>${num(g.wallVolume)} m³</strong></div></div><button data-up="opening">Thêm cửa đi / cửa sổ</button>${g.issues.map(x=>`<p class="danger">${esc(x)}</p>`).join('')}<div class="tablewrap"><table><thead><tr><th>Cửa</th><th>Tường</th><th>Kích thước / cao đáy</th><th></th></tr></thead><tbody>${state.openings.map(o=>`<tr><td>${o.kind==='door'?'Cửa đi':'Cửa sổ'}</td><td>${esc(o.wallId)}</td><td>${num(o.width)} × ${num(o.height)} m / ${num(o.sill)} m</td><td><button class="small" data-up="editOpening" data-id="${esc(o.id)}">Sửa</button><button class="small" data-up="deleteOpening" data-id="${esc(o.id)}">Xóa</button></td></tr>`).join('')}</tbody></table></div></section>`;};
const oldPlan=planSvg;
planSvg=function(interactive=true,floor=state.floor){let svg=oldPlan(interactive,floor);const g=snapshot().geometry;const marks=g.openings.map(o=>{const w=g.walls.find(w=>w.id===o.wallId);if(w.floor!==floor)return'';const a=w.a+o.offset,b=a+o.width;const line=w.axis==='h'?`x1="${a*30}" y1="${w.c*30}" x2="${b*30}" y2="${w.c*30}"`:`x1="${w.c*30}" y1="${a*30}" x2="${w.c*30}" y2="${b*30}"`;if(o.kind==='window')return `<line ${line} stroke="#4b95b1" stroke-width="5" pointer-events="none"><title>Cửa sổ</title></line>`;const hingeA=a*30,leaf=o.width*30,c=w.c*30;if(w.axis==='h')return `<g pointer-events="none" stroke="#b8795d" fill="none"><line x1="${hingeA}" y1="${c}" x2="${hingeA}" y2="${c+leaf}" stroke-width="1.5"/><path d="M ${b*30} ${c} A ${leaf} ${leaf} 0 0 0 ${hingeA} ${c+leaf}" stroke-width="1"/><title>Cửa đi · ký hiệu mở 90°</title></g>`;return `<g pointer-events="none" stroke="#b8795d" fill="none"><line x1="${c}" y1="${hingeA}" x2="${c+leaf}" y2="${hingeA}" stroke-width="1.5"/><path d="M ${c} ${b*30} A ${leaf} ${leaf} 0 0 1 ${c+leaf} ${hingeA}" stroke-width="1"/><title>Cửa đi · ký hiệu mở 90°</title></g>`;}).join('');return svg.replace('</svg>',marks+'</svg>');};
const oldFinance=screens[1];
screens[1]=c=>oldFinance(c)+`<section class="card upgrade"><h2>Tiền theo tiến độ thi công</h2><div class="fields">${field('Thi công · tháng','constructionMonths',{min:1,max:60})}${field('Giữ lại bảo hành · %','retentionPercent',{min:0,max:30,step:.1})}${field('Trả giữ lại sau hoàn thành · tháng','retentionDelay',{min:0,max:60})}${field('Phí giải ngân · % khoản nhận','loanFeePercent',{min:0,max:20,step:.1})}${field('Thu nhập so với ban đầu · hệ số','incomeFactor',{min:0,max:2,step:.1})}</div><p>Giải ngân khoản vay: ${state.loanDraws.map(d=>`tháng ${d.month}: ${num(d.percent)}%`).join(' · ')}</p><button data-up="draws">Sửa lịch nhận tiền vay</button><button data-up="cashCsv">Tải dòng tiền CSV</button><p class="hint">Giải ngân đầu tháng; tính lãi trên dư nợ đã nhận. Khi nhận thêm tiền, khoản trả được tính lại theo kỳ hạn còn lại. Tiến độ chi thi công chia đều theo số tháng đã nhập, phần giữ lại trả riêng. Đây là lịch giả định, chưa theo hợp đồng cụ thể.</p>${cashTable(c.snapshot)}</section>`;
function cashTable(s,limit=24){const rows=s.monthly.slice(0,Math.min(s.monthly.length,Math.max(state.constructionMonths+state.retentionDelay,limit)));return `<div class="notice">Tháng đầu thiếu tiền: <b>${s.monthly.find(r=>r.cashShortfall>0)?.month??'không có'}</b> · Tháng đầu chạm quỹ giữ lại: <b>${s.monthly.find(r=>r.reserveGap>0)?.month??'không có'}</b>. Đây là dòng tiền kế hoạch; sổ chi thực tế được theo dõi riêng, không trừ hai lần.</div><div class="tablewrap"><table><thead><tr><th>Tháng</th><th>Vay nhận</th><th>Trả vay + phí</th><th>Chi xây</th><th>Số dư</th><th>Thiếu so quỹ giữ lại</th></tr></thead><tbody>${rows.map(r=>`<tr class="${r.cashShortfall?'danger':''}"><td>${r.month}</td><td>${money(r.loanDraw)}</td><td>${money(r.loanPayment)}</td><td>${money(r.construction)}</td><td>${money(r.closingBalance)}</td><td>${money(r.reserveGap)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Bảng xem trước ${rows.length}/${s.monthly.length} tháng. CSV chứa toàn bộ kỳ hạn.</p>`;}
screens[5]=c=>`<section class="card"><div class="row between"><h2>Giá có nguồn theo hạng mục</h2><button data-up="importPrices">Nhập bảng giá JSON</button><button data-up="exportPrices">Tải bảng giá JSON</button></div><p>Nhập nguồn báo giá và địa phương. Giá thủ công không bị nhân theo gói hoàn thiện; hệ số gói chỉ áp dụng giá DEMO. Các dòng mẫu là phạm vi minh họa, cần kiểm tra phần vật liệu/nhân công có bị trùng trong báo giá của ông.</p>${statusNote(c.snapshot)}<div class="tablewrap"><table><thead><tr><th>Hạng mục</th><th>Giá / đơn vị</th><th>Nguồn, ngày, vùng</th><th></th></tr></thead><tbody>${Core.PRICE_ITEMS.map(d=>{const p=state.prices.find(p=>p.id===d.id);return `<tr><td>${esc(d.name)}</td><td>${p?.price===null||!p?'Chưa có':money(p.price)} / ${d.unit}</td><td>${esc(p?.source??'Chưa có nguồn')}<small class="source">${esc(p?.date??'')} · ${esc(p?.region??'')} · ${p?.kind==='manual_quote'?'Người dùng nhập, chưa xác minh':'DEMO'}</small></td><td><button data-up="price" data-id="${d.id}">Sửa</button></td></tr>`;}).join('')}</tbody></table></div><div class="fields">${field('Dự phòng công trình · tỷ lệ (0,12 = 12%)','contingencyRate',{min:0,max:1,step:.01})}</div>${c.snapshot.priceFlags.map(f=>`<p class="hint">${esc(f)}</p>`).join('')}</section><section class="card upgrade"><h2>Khối lượng và chi phí</h2>${table(c)}</section>`;
screens[6]=c=>`<div class="twocol"><section class="card"><div class="row between"><h2>Mô hình khối 3D từ mặt bằng</h2><select id="sceneFloor" aria-label="Tầng 3D"><option value="all">Tất cả tầng</option>${Array.from({length:state.floors},(_,i)=>`<option value="${i}">Tầng ${i+1}</option>`).join('')}</select></div><canvas id="scene3d" tabindex="0" aria-label="Mô hình 3D; kéo xoay, lăn chuột thu phóng, phím mũi tên xoay"></canvas><p class="hint">Kéo để xoay, lăn chuột/+/− để zoom, phím mũi tên để xoay. Hình khối phối cảnh từ cùng dữ liệu tường/cửa; chưa phải phối cảnh hoàn thiện hoặc mô hình kết cấu.</p><button data-up="obj">Tải mô hình OBJ</button></section><section class="card"><h2>Kiểm tra theo dữ liệu</h2>${Core.reviewFacts(c.snapshot).map(f=>`<p class="${f.severity==='warning'?'notice':'hint'}"><b>${esc(f.id)}</b>: ${esc(f.text)}</p>`).join('')}<h3>AI giải thích phương án</h3><p class="hint">AI nhận các kết quả kiểm tra ở trên và mã phiên bản; không gửi tên, địa chỉ hoặc file bản vẽ. Nội dung AI có thể sai, không xác nhận an toàn kỹ thuật.</p><button data-up="ai" ${aiBusy?'disabled':''}>${aiBusy?'Đang phân tích…':'Gửi dữ liệu kiểm tra cho AI'}</button><button data-up="aiPrompt">Tải yêu cầu AI để dùng bên ngoài</button><button data-up="aiImport">Nhập nhận xét JSON</button><div id="aiStatus" role="status">${aiMarkup(c.snapshot)}</div></section></div><section class="card upgrade"><h2>Chi phí sở hữu 10 năm</h2><div class="fields">${field('Bảo trì · % chi phí xây/năm','maintenance',{min:0,max:10,step:.1})}${field('Vận hành mỗi năm · triệu đồng','annualOperating',{min:0,max:10000,step:1})}${field('Lạm phát giả định · %/năm','annualInflation',{min:0,max:30,step:.1})}</div>${lifeTable(c.snapshot)}</section>`;
function lifeTable(s){const l=Core.lifecycle({initialCost:s.quote.total,annualOperatingCost:Math.round(state.annualOperating*1e6),annualMaintenanceCost:Math.round(s.quote.baseTotal*state.maintenance/100),inflationRate:state.annualInflation/100});return `<div class="metric"><small>Tổng chi phí sở hữu theo giả định 10 năm</small><strong>${money(l.nominalTotal)}</strong></div><p class="hint">Không cộng gốc vay lần hai; không gồm lãi vay/giá trị bán lại. Bảo trì do ông nhập, không dự đoán vật liệu hỏng.</p><div class="tablewrap"><table><thead><tr><th>Năm</th><th>Vận hành</th><th>Bảo trì</th><th>Tích lũy gồm xây</th></tr></thead><tbody>${l.rows.map(r=>`<tr><td>${r.year}</td><td>${money(r.operations)}</td><td>${money(r.maintenance)}</td><td>${money(r.cumulative)}</td></tr>`).join('')}</tbody></table></div>`;}
screens[7]=c=>`<div class="metrics4"><div class="metric"><small>Vốn trừ quỹ giữ lại</small><strong>${money(c.budget)}</strong></div><div class="metric"><small>Tổng phần đã tính</small><strong>${money(c.total)}</strong></div><div class="metric"><small>Chênh ngân sách</small><strong>${money(c.budget-c.total)}</strong></div></div><section class="card upgrade"><h2>Dự toán cùng phiên bản dữ liệu</h2>${table(c)}<h3>Phạm vi chưa bao gồm / cần xác minh</h3>${c.snapshot.exclusions.map(x=>`<p class="hint">${esc(x)}</p>`).join('')}<button data-action="snapshot">Lưu phương án</button><button data-action="print">In hồ sơ PDF</button><button data-up="snapshotJson">Tải snapshot tính toán</button></section>`;
const oldExport=screens[9];screens[9]=c=>oldExport(c)+`<section class="card upgrade"><h2>Bộ hồ sơ nhất quán</h2>${statusNote(c.snapshot)}<button data-up="bundle">Tải ZIP hồ sơ</button><button data-up="cashCsv">Dòng tiền CSV</button><button data-up="obj">Mô hình OBJ</button><p class="hint">ZIP gồm HTML để in PDF, CSV dự toán/khối lượng/trả nợ/dòng tiền, SVG, OBJ và snapshot JSON. Chưa có XLSX có công thức hoặc PDF sinh trực tiếp.</p></section>`;
const oldRender=render;render=function(){oldRender();if(state.step===6&&view==='steps')globalThis.BMHScene.mount(document.querySelector('#scene3d'),snapshot(),document.querySelector('#sceneFloor'));};
versions=function(){const c=calc();return `<div class="heading"><h1>Các phương án · bộ tính ${Core.ENGINE_VERSION}</h1><button data-action="snapshot">Lưu phương án hiện tại</button></div><section class="card"><p>Hiện tại: ${money(c.total)}. Mỗi phương án mở lại giữ dữ liệu giá và đầu vào riêng.</p>${state.snapshots.map((s,i)=>{let snap;try{snap=Core.buildSnapshot({...Core.defaultUpgrade(),...s.data});}catch{}return `<div class="historycard"><div><b>${esc(s.title)}</b><p>${snap?money(snap.quote.total):'Cần sửa dữ liệu'} · ${esc(snap?.id??'')}</p><small>Tính lại bằng ${Core.ENGINE_VERSION}; số lịch sử trước nâng cấp: ${money(s.total)}. Chênh hiện tại: ${snap?money(snap.quote.total-c.total):'—'}</small></div><button data-action="loadSnapshot" data-value="${i}">Mở</button></div>`;}).join('')}</section>`;};
function aiMarkup(s){return aiResult?(aiResult.snapshotId===s.id?aiResult.insights.map(i=>`<p>${esc(i.text)}<small class="source">Dữ liệu: ${i.evidenceIds.map(esc).join(', ')}</small></p>`).join(''):'<p>Nhận xét cũ: dữ liệu đã thay đổi. Hãy yêu cầu lại.</p>'):'Chưa có nhận xét AI. GitHub Pages cần dùng tệp yêu cầu hoặc chạy máy chủ AI cục bộ.';}
function aiPayload(s){return{snapshotId:s.id,facts:Core.reviewFacts(s)};}
function editDialog(title,content,handler){modal(`<h2>${title}</h2><form id="upgradeForm" class="stack">${content}<p id="formError" class="danger" role="alert"></p><button type="submit" class="primary">Lưu thay đổi</button></form>`);$('#upgradeForm').onsubmit=e=>{e.preventDefault();try{handler(Object.fromEntries(new FormData(e.target)));cachedKey='';save();$('#modal').close();render();}catch(err){$('#formError').textContent=err.message;}};}
const input=(name,label,value,type='number',more='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
function priceDialog(id){const def=Core.PRICE_ITEMS.find(d=>d.id===id),p=state.prices.find(p=>p.id===id)||{...Core.defaultUpgrade().prices.find(p=>p.id===id),price:null};editDialog('Báo giá: '+def.name,input('price','Đơn giá VND/'+def.unit+' (để trống nếu chưa có)',p.price??'','number','min="0" max="1000000000000" step="1"')+input('source','Nguồn / số báo giá',p.source,'text','required maxlength="300"')+input('sourceUrl','Đường dẫn nguồn (không bắt buộc)',p.sourceUrl,'url')+input('date','Ngày báo giá',p.date,'date','required')+input('region','Địa phương áp dụng',p.region==='DEMO'?state.location:p.region,'text','required')+`<label class="field">Loại dữ liệu<select name="kind"><option value="manual_quote">Báo giá tôi nhập (chưa xác minh)</option><option value="demo" ${p.kind==='demo'?'selected':''}>Minh họa DEMO</option></select></label>`+input('tax','Thuế · %',p.taxRate*100,'number','min="0" max="100" step="0.1"')+input('waste','Hao hụt · %',p.wasteRate*100,'number','min="0" max="100" step="0.1"'),f=>{const record={id,unit:def.unit,price:f.price===''?null:Number(f.price),source:f.source,sourceUrl:f.sourceUrl,date:f.date,region:f.region,kind:f.kind,taxRate:Number(f.tax)/100,wasteRate:Number(f.waste)/100};const next=[...state.prices.filter(p=>p.id!==id),record];Core.validateUpgrade({...state,prices:next});state.prices=next;});}
function openingDialog(id){const g=snapshot().geometry,o=state.openings.find(o=>o.id===id)||{id:'o'+Date.now(),wallId:g.walls.find(w=>w.floor===state.floor)?.id,kind:'door',width:.9,height:2.1,offset:0,sill:0};if(!g.walls.length)return toast('Cần thêm phòng trước.');editDialog('Cửa gắn vào đoạn tường',`<label class="field">Đoạn tường<select name="wallId">${g.walls.map(w=>`<option value="${w.id}" ${w.id===o.wallId?'selected':''}>Tầng ${w.floor+1} · ${w.id} · dài ${num(w.length)}m</option>`).join('')}</select></label><label class="field">Loại<select name="kind"><option value="door">Cửa đi</option><option value="window" ${o.kind==='window'?'selected':''}>Cửa sổ</option></select></label>`+input('width','Rộng · m',o.width,'number','min="0.1" step="0.1" required')+input('height','Cao · m',o.height,'number','min="0.1" step="0.1" required')+input('offset','Cách đầu đoạn tường · m',o.offset,'number','min="0" step="0.1" required')+input('sill','Cao đáy cửa so sàn · m',o.sill,'number','min="0" step="0.1" required'),f=>{const record={id:o.id,wallId:f.wallId,kind:f.kind,width:+f.width,height:+f.height,offset:+f.offset,sill:+f.sill};const next=[...state.openings.filter(x=>x.id!==o.id),record],result=Core.takeoff({...state,openings:next});if(!result.openings.some(x=>x.id===o.id))throw Error('Cửa vượt tường hoặc chồng cửa khác');state.openings=next;});}
function readJson(handler){const f=document.createElement('input');f.type='file';f.accept='.json,application/json';f.onchange=async()=>{try{if(!f.files[0]||f.files[0].size>5e6)throw Error('Tệp tối đa 5 MB');handler(JSON.parse(await f.files[0].text()));cachedKey='';save();render();}catch(e){toast('Không thể nhập: '+e.message);}};f.click();}
app.addEventListener('click',async e=>{const b=e.target.closest('[data-up]');if(!b)return;const a=b.dataset.up,id=b.dataset.id;try{
 if(a==='price')return priceDialog(id);
 if(a==='opening'||a==='editOpening')return openingDialog(id);
 if(a==='deleteOpening'){state.openings=state.openings.filter(o=>o.id!==id);save();render();return;}
 if(a==='draws')return editDialog('Lịch giải ngân khoản vay',`<p>Mỗi dòng: tháng, phần trăm. Tổng 100%. Khoản nhận đầu tháng sẽ bắt đầu tính lãi ngay trong tháng đó.</p><textarea name="draws" rows="6">${state.loanDraws.map(d=>d.month+','+d.percent).join('\n')}</textarea>`,f=>{const draws=f.draws.trim().split('\n').map(l=>{const [month,percent]=l.split(',').map(Number);return{month,percent};}).sort((a,b)=>a.month-b.month);Core.projectLoan({...state,loanDraws:draws});Core.validateUpgrade({...state,loanDraws:draws});state.loanDraws=draws;});
 if(a==='exportPrices')return download('BMH-gia-co-nguon.json',JSON.stringify({prices:state.prices},null,2),'application/json');
 if(a==='importPrices')return readJson(d=>{const next=Core.validateUpgrade({...state,prices:d.prices});state.prices=next.prices;});
 if(a==='snapshotJson')return download(snapshot().id+'.json',JSON.stringify(snapshot(),null,2),'application/json');
 if(a==='cashCsv')return download(snapshot().id+'-dong-tien.csv',cashCsv(snapshot()),'text/csv;charset=utf-8');
 if(a==='obj')return download(snapshot().id+'.obj',BMHScene.obj(snapshot()),'text/plain');
 if(a==='bundle')return bundle(snapshot());
 if(a==='aiPrompt')return download(snapshot().id+'-ai-request.json',JSON.stringify({instruction:'Giải thích bằng tiếng Việt, chỉ dùng facts làm bằng chứng; không khẳng định an toàn hay tự sửa tiền. Trả JSON {snapshotId, insights:[{text,evidenceIds}]}.',...aiPayload(snapshot())},null,2),'application/json');
 if(a==='aiImport')return readJson(d=>{aiResult=Core.validateReview(d,snapshot());});
 if(a==='ai'){
  if(!['localhost','127.0.0.1'].includes(location.hostname))return toast('GitHub Pages không có máy chủ AI. Dùng npm start cục bộ với cấu hình AI hoặc tải yêu cầu JSON.');
  if(!confirm('Gửi các kết quả kiểm tra ngân sách, hình học và dòng tiền đang hiển thị tới OpenAI qua máy chủ cục bộ?'))return;
  const s=snapshot();aiBusy=true;render();
  try{const response=await fetch('api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(aiPayload(s)),signal:AbortSignal.timeout(45000)});const data=await response.json();if(!response.ok)throw Error(data.error||'AI không phản hồi');aiResult=Core.validateReview(data,s);if(snapshot().id!==s.id)toast('Dữ liệu đã thay đổi; nhận xét được đánh dấu cũ.');}finally{aiBusy=false;render();}
 }
}catch(err){toast(err.message);}});
// Intercept all exports to guarantee one snapshot and consistent identifiers.
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='addRoom'&&state.rooms.length>=250){e.stopImmediatePropagation();toast('Tối đa 250 phòng cho bản này.');return;}if(!['costCsv','loanCsv','svg','print'].includes(a))return;e.stopImmediatePropagation();const s=snapshot();if(a==='costCsv')download(s.id+'-du-toan.csv',costCsv(s),'text/csv;charset=utf-8');if(a==='loanCsv')download(s.id+'-tra-no.csv',loanCsv(s),'text/csv;charset=utf-8');if(a==='svg')download(s.id+'-mat-bang.svg',allSvg(s),'image/svg+xml');if(a==='print')report();},true);
function toCsv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let x=String(v??'');if(/^[=+@\-]/.test(x)&&typeof v!=='number')x="'"+x;return '"'+x.replace(/"/g,'""')+'"';}).join(',')).join('\r\n');}
function costCsv(s){return toCsv([['Snapshot',s.id,'Status',s.status],['Hạng mục','Khối lượng gốc','Hao hụt','Đơn vị','Đơn giá trước thuế','Thuế','Thành tiền','Nguồn','Ngày','Vùng','URL'],...s.quote.items.map(i=>[i.description,i.quantity,i.wasteRate,i.unit,i.unitPrice,i.taxRate,i.total,i.priceSource,i.priceDate,i.region,i.sourceUrl]),['Dự phòng','','','','','',s.quote.constructionContingency],['Tổng phần đã tính','','','','','',s.quote.total],['Thiếu giá',s.missing.join('; ')],['Loại trừ',s.exclusions.join('; ')]]);}
function loanCsv(s){return toCsv([['Snapshot',s.id],['Tháng','Nhận vay','Gốc','Lãi','Phí','Tổng trả','Dư nợ'],...s.loans.map(r=>[r.month,r.loanDraw,r.principalPaid,r.interest,r.fee,r.payment,r.closingBalance])]);}
function cashCsv(s){return toCsv([['Snapshot',s.id],['Tháng','Số dư đầu','Thu nhập','Nhận vay','Sinh hoạt','Nợ cũ','Trả vay','Chi xây kế hoạch','Số dư cuối','Thiếu tiền','Thiếu quỹ dự phòng'],...s.monthly.map(r=>[r.month,r.openingBalance,r.income,r.loanDraw,r.livingCosts,r.existingDebt,r.loanPayment,r.construction,r.closingBalance,r.cashShortfall,r.reserveGap])]);}
function allSvg(s){const W=state.width*30+64,H=state.depth*30+100;return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H*state.floors+50}"><rect width="100%" height="100%" fill="white"/><text x="5" y="15" font-size="8">${esc(s.id)} · ${esc(s.status)}</text>${Array.from({length:state.floors},(_,f)=>`<svg y="${f*H+40}" width="${W}" height="${H}" viewBox="-32 -45 ${W} ${H}"><text y="-32" font-size="10">Tầng ${f+1}</text>${planSvg(false,f).replace(/^<svg[^>]*>/,'').replace(/<\/svg>$/,'')}</svg>`).join('')}</svg>`;}
function reportBody(s){return `<h1>Build My Home · ${esc(state.name)}</h1><p>${esc(state.location)} · ${esc(s.asOf)} · bộ tính ${s.engineVersion}</p>${table({snapshot:s,contingency:s.quote.constructionContingency,total:s.quote.total})}<h2>Khối lượng ý tưởng</h2><p>Diện tích hợp: ${num(s.geometry.floorArea)} m²; tường: ${num(s.geometry.wallLength)} m; tường trừ cửa: ${num(s.geometry.wallArea)} m². ${esc(s.geometry.basis)}</p><h2>Giới hạn và cảnh báo</h2>${[...s.warnings,...s.priceFlags,...s.exclusions].map(t=>`<p>${esc(t)}</p>`).join('')}<h2>Tài chính kế hoạch</h2><p>Vốn sau quỹ giữ lại ${money(s.budget)}; tổng dự toán ${money(s.quote.total)}; chênh ${money(s.budgetGap)}. Khoản trả vay cao nhất ${money(s.peakPayment)}.</p>${cashTable(s)}<h2>Giả định</h2><p>Thi công ${state.constructionMonths} tháng, giữ lại ${state.retentionPercent}%, trả sau ${state.retentionDelay} tháng. Lãi ${state.rate}% trong ${state.promo} tháng đầu, sau đó ${state.postRate}%. Phí giải ngân ${state.loanFeePercent}%.</p><h2>Mặt bằng từng tầng</h2>${allSvg(s)}<h2>Khoản chi thực tế (tách khỏi kế hoạch)</h2>${state.spending.map(r=>`<p>${esc(r.date)} · ${esc(r.name)} · ${money(r.amount)}</p>`).join('')||'<p>Chưa ghi nhận.</p>'}`;}
report=function(){const s=snapshot();$('.report')?.remove();const div=document.createElement('article');div.className='report';div.innerHTML=reportBody(s);document.body.append(div);window.print();};
// ZIP store writer (UTF-8, CRC32); outputs files without third-party dependencies.
function zipFiles(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;const u16=(v,o,n)=>v.setUint16(o,n,true),u32=(v,o,n)=>v.setUint32(o,n>>>0,true);const crc=bytes=>{let c=0xffffffff;for(const b of bytes){c^=b;for(let j=0;j<8;j++)c=(c>>>1)^((c&1)?0xedb88320:0);}return(c^0xffffffff)>>>0;};
 for(const [name,text] of Object.entries(files)){const n=encoder.encode(name),data=encoder.encode(text),sum=crc(data),h=new Uint8Array(30+n.length),v=new DataView(h.buffer);u32(v,0,0x04034b50);u16(v,4,20);u16(v,6,0x800);u32(v,14,sum);u32(v,18,data.length);u32(v,22,data.length);u16(v,26,n.length);h.set(n,30);parts.push(h,data);const c=new Uint8Array(46+n.length),cv=new DataView(c.buffer);u32(cv,0,0x02014b50);u16(cv,4,20);u16(cv,6,20);u16(cv,8,0x800);u32(cv,16,sum);u32(cv,20,data.length);u32(cv,24,data.length);u16(cv,28,n.length);u32(cv,42,offset);c.set(n,46);central.push(c);offset+=h.length+data.length;}
 const end=new Uint8Array(22),ev=new DataView(end.buffer);u32(ev,0,0x06054b50);u16(ev,8,central.length);u16(ev,10,central.length);u32(ev,12,central.reduce((s,c)=>s+c.length,0));u32(ev,16,offset);return new Blob([...parts,...central,end],{type:'application/zip'});
}
function bundle(s){const files={'snapshot.json':JSON.stringify(s,null,2),'du-toan.csv':costCsv(s),'tra-no.csv':loanCsv(s),'dong-tien.csv':cashCsv(s),'mat-bang.svg':allSvg(s),'mo-hinh.obj':BMHScene.obj(s),'khoi-luong.csv':toCsv([['Snapshot',s.id],['Đại lượng','Giá trị','Đơn vị'],['Diện tích hợp',s.geometry.floorArea,'m2'],['Chiều dài tường',s.geometry.wallLength,'m'],['Tường trừ cửa',s.geometry.wallArea,'m2'],['Thể tích tường sơ bộ',s.geometry.wallVolume,'m3'],['Sơn hai mặt',s.geometry.paintArea,'m2']]),'bao-cao.html':'<!doctype html><html lang="vi"><meta charset="utf-8"><title>'+esc(s.id)+'</title><style>body{font:14px system-ui;max-width:1000px;margin:30px auto}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:6px;text-align:left}small{display:block}svg{max-width:100%;max-height:900px}.notice{padding:12px;background:#f1eee6}button{display:none}@media print{table{font-size:10px}svg{break-before:page}}</style>'+reportBody(s)+'</html>','DOC_TOI.txt':`Mã hồ sơ ${s.id}. Mở bao-cao.html rồi In > Lưu PDF. Tất cả bảng lấy cùng snapshot. Đây là hồ sơ ý tưởng; đọc cảnh báo giá và phạm vi trước khi sử dụng.`};const url=URL.createObjectURL(zipFiles(files)),a=document.createElement('a');a.href=url;a.download=s.id+'-ho-so.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
// Validate numerical edits before legacy mutation handlers run.
app.addEventListener('change',e=>{const t=e.target;if(!t.dataset.key)return;const k=t.dataset.key;let value=t.type==='checkbox'?t.checked:t.type==='number'||t.type==='range'?Number(t.value):t.value;const draft={...state,[k]:value};if(['width','depth','floors'].includes(k))draft.rooms=state.rooms.filter(r=>r.floor<draft.floors).map(r=>({...r,w:Math.min(r.w,draft.width),h:Math.min(r.h,draft.depth),x:Math.max(0,Math.min(r.x,draft.width-Math.min(r.w,draft.width))),y:Math.max(0,Math.min(r.y,draft.depth-Math.min(r.h,draft.depth)))}));try{Core.buildSnapshot(draft);}catch(err){e.stopImmediatePropagation();t.value=state[k];toast('Không lưu thay đổi: '+err.message);}},true);
